/*!
 * wega-music.js - Music pack for "Wega's Challenge: The Idol" VR (fan recreation)
 * ---------------------------------------------------------------------------
 * Contains every music track embedded as base64 MP3, plus a tiny Web Audio
 * player (WegaMusic) with seamless looping, crossfades, muffle (low-pass),
 * playback-rate control and an analyser for beat-reactive visuals.
 *
 * Tracks:
 *   "lap1"  WEXECUTION  - Lap 1 theme  (~1:40, loops)
 *   "lap2"  WEGAFADENCE - Lap 2 theme  (~3:14, loops; volume-matched to lap1)
 *
 * Usage (classic script, no modules needed):
 *   <script src="wega-music.js"></script>
 *   // after ANY user gesture (button click, "Enter VR" press, trigger pull):
 *   await WegaMusic.init();                 // creates/resumes AudioContext, decodes tracks
 *   WegaMusic.play("lap1");                 // start lap 1 (loops)
 *   WegaMusic.crossfadeTo("lap2", 1.5);     // lap 2 transition
 *   WegaMusic.setMuffled(true);             // lobby / pause low-pass
 *   WegaMusic.setRate(1.06);                // escape-phase speed-up
 *   WegaMusic.getLevel();                   // 0..1 loudness for pulsing visuals
 *   WegaMusic.stop(2);                      // fade out over 2 s
 *
 * Sections: play / crossfadeTo take an offset and a loop of their own, so one track can hold several parts
 * (WEGA FACE's theme: one part per phase; RORY'S CHALLENGE: the drop loops in overtime):
 *   WegaMusic.crossfadeTo("boss", 1.2, 120.25, { start: 178.5, end: 260.1 });   // from 120.25 s, loop 178.5-260.1
 *   WegaMusic.play("rory", 0.05, 12.3, false);                                  // from 12.3 s, no loop
 *   WegaMusic.position();                   // where in the track it is right now (loops included)
 *
 * You can also pass your own AudioContext: WegaMusic.init(myCtx)
 * Raw data:  WEGA_MUSIC_DATA.lap1.src  -> "data:audio/mpeg;base64,..."
 */
(function (global) {
"use strict";
var WEGA_MUSIC_DATA = {
  "lap1": {
    title: "WEXECUTION (Lap 1 Theme)",
    credit: "Wega's Challenge: The Idol OST - fanmade visualizer upload by Santy",
    duration: 99.624,
    loopStart: 0.211,
    loopEnd: 99.624,
    gain: 1.0,
    src: "data:audio/mpeg;base64,"
  },
  "lap2": {
    title: "WEGAFADENCE (Lap 2 Theme)",
    credit: "Wega's Challenge: The Idol OST - upload by GAMR",
    duration: 195.187,
    loopStart: 0.078,
    loopEnd: 193.98,
    gain: 3.2,
    src: "data:audio/mpeg;base64,"
  }
};

function b64ToArrayBuffer(dataUrl) {
  var b64 = dataUrl.slice(dataUrl.indexOf(",") + 1);
  var bin = atob(b64), len = bin.length, bytes = new Uint8Array(len);
  for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

var ctx = null, master = null, filter = null, analyser = null, levelData = null;
var buffers = {}, current = null, initPromise = null, rate = 1, volume = 0.8, muffled = false;
var listeners = {};

function emit(ev, arg) { (listeners[ev] || []).forEach(function (fn) { try { fn(arg); } catch (e) { console.error(e); } }); }

function decode(name) {
  var t = WEGA_MUSIC_DATA[name];
  return new Promise(function (res, rej) {
    var ab = b64ToArrayBuffer(t.src);
    // callback form for older Quest/Oculus Browser builds, promise form otherwise
    var p = ctx.decodeAudioData(ab, function (buf) { res(buf); }, function (e) { rej(e); });
    if (p && p.then) p.then(res, rej);
  }).then(function (buf) { buffers[name] = buf; return buf; });
}

// loop: undefined = the track's own loop, { start, end } = loop that part of it, false = play once
function makeVoice(name, offset, loop) {
  var t = WEGA_MUSIC_DATA[name], buf = buffers[name];
  var ls = t.loopStart, le = t.loopEnd;
  if (loop && loop.end > loop.start) { ls = loop.start; le = loop.end; }
  var src = ctx.createBufferSource();
  src.buffer = buf;
  src.loop = loop !== false;
  src.loopStart = Math.min(ls, buf.duration);
  src.loopEnd = Math.min(le, buf.duration);
  src.playbackRate.value = rate;
  var g = ctx.createGain();
  g.gain.value = 0;
  src.connect(g); g.connect(filter);
  var at = offset != null ? Math.max(0, Math.min(offset, buf.duration - 0.05)) : (loop && loop.start != null ? loop.start : t.loopStart);
  src.start(0, at);
  return { name: name, src: src, gain: g, trackGain: t.gain, startedAt: ctx.currentTime, offset: at, loop: src.loop, loopStart: src.loopStart, loopEnd: src.loopEnd };
}

function fadeVoice(v, to, secs) {
  var now = ctx.currentTime, p = v.gain.gain;
  p.cancelScheduledValues(now);
  p.setValueAtTime(p.value, now);
  if (secs > 0) p.linearRampToValueAtTime(to, now + secs); else p.setValueAtTime(to, now);
}

function killVoice(v, secs) {
  fadeVoice(v, 0, secs);
  try { v.src.stop(ctx.currentTime + Math.max(secs, 0) + 0.05); } catch (e) {}
}

var WegaMusic = {
  data: WEGA_MUSIC_DATA,
  tracks: Object.keys(WEGA_MUSIC_DATA),

  /** Create/resume the AudioContext and decode all tracks. Call from a user gesture. */
  init: function (existingCtx) {
    if (initPromise) { if (ctx && ctx.state === "suspended") ctx.resume(); return initPromise; }
    var AC = global.AudioContext || global.webkitAudioContext;
    ctx = existingCtx || new AC();
    master = ctx.createGain(); master.gain.value = volume;
    filter = ctx.createBiquadFilter(); filter.type = "lowpass"; filter.frequency.value = 22000; filter.Q.value = 0.7;
    analyser = ctx.createAnalyser(); analyser.fftSize = 256; analyser.smoothingTimeConstant = 0.6;
    levelData = new Uint8Array(analyser.frequencyBinCount);
    filter.connect(master); master.connect(analyser); analyser.connect(ctx.destination);
    if (ctx.state === "suspended") ctx.resume();
    initPromise = Promise.all(WegaMusic.tracks.map(decode)).then(function () { emit("ready"); return WegaMusic; });
    return initPromise;
  },

  isReady: function () { return WegaMusic.tracks.every(function (n) { return !!buffers[n]; }); },
  getContext: function () { return ctx; },
  /** Node you can connect your own SFX to so they share master volume (not the muffle filter). */
  getMasterNode: function () { return master; },
  getAnalyser: function () { return analyser; },

  /** Hard-start a track (short 0.05 s de-click fade), optionally `offset` seconds in, optionally with its own `loop`. */
  play: function (name, fadeIn, offset, loop) {
    if (!buffers[name]) { console.warn("[WegaMusic] not ready or unknown track:", name); return; }
    if (ctx.state === "suspended") ctx.resume();
    if (current) killVoice(current, 0.05);
    var t = WEGA_MUSIC_DATA[name];
    current = makeVoice(name, offset != null && offset > 0 ? Math.min(offset, Math.max(t.loopStart, buffers[name].duration - 0.05)) : (loop != null ? offset : null), loop);
    fadeVoice(current, current.trackGain, fadeIn != null ? fadeIn : 0.05);
    emit("trackchange", name);
  },

  /** Equal-time crossfade from whatever is playing to `name` (with an offset / loop: also to another part of the same track). */
  crossfadeTo: function (name, secs, offset, loop) {
    secs = secs == null ? 1.5 : secs;
    if (!buffers[name]) { console.warn("[WegaMusic] not ready or unknown track:", name); return; }
    if (current && current.name === name && offset == null && loop == null) return;
    if (current) killVoice(current, secs);
    current = makeVoice(name, offset, loop);
    fadeVoice(current, current.trackGain, secs);
    emit("trackchange", name);
  },

  /** Fade out and stop. */
  stop: function (secs) {
    if (!current) return;
    killVoice(current, secs == null ? 0.5 : secs);
    current = null;
    emit("trackchange", null);
  },

  /** Restart current track from its loop start (e.g. on lap restart). */
  restart: function () { if (current) WegaMusic.play(current.name); },

  currentTrack: function () { return current ? current.name : null; },

  /** Seconds since the current track started (playback-rate scaled, ignores loops). */
  elapsed: function () { return current ? (ctx.currentTime - current.startedAt) * rate + (current.offset || 0) : 0; },

  /** Where in the current track it is right now, in seconds (its loop wrapped in; playback-rate scaled). */
  position: function () {
    if (!current) return 0;
    var p = WegaMusic.elapsed(), L = current.loopEnd - current.loopStart;
    if (current.loop && L > 0.05 && p >= current.loopEnd) p = current.loopStart + (p - current.loopStart) % L;
    return p;
  },

  /** The current voice's loop: { start, end }, or false when it plays once. */
  currentLoop: function () { return current ? (current.loop ? { start: current.loopStart, end: current.loopEnd } : false) : null; },

  /** Master volume 0..1 */
  setVolume: function (v, secs) {
    volume = Math.max(0, Math.min(1, v));
    if (!master) return;
    var now = ctx.currentTime; master.gain.cancelScheduledValues(now);
    master.gain.setValueAtTime(master.gain.value, now);
    master.gain.linearRampToValueAtTime(volume, now + (secs || 0.1));
  },
  getVolume: function () { return volume; },

  /** Low-pass "underwater / pause menu / lobby" effect. */
  setMuffled: function (on, secs) {
    muffled = !!on;
    if (!filter) return;
    var now = ctx.currentTime, f = filter.frequency;
    f.cancelScheduledValues(now); f.setValueAtTime(f.value, now);
    f.exponentialRampToValueAtTime(muffled ? 600 : 22000, now + (secs || 0.4));
  },
  isMuffled: function () { return muffled; },

  /** Playback speed (also shifts pitch). 1 = normal. Good for "RUN FOR YOUR LIFE": 1.05-1.1 */
  setRate: function (r, secs) {
    rate = r;
    if (!current) return;
    var now = ctx.currentTime, p = current.src.playbackRate;
    p.cancelScheduledValues(now); p.setValueAtTime(p.value, now);
    p.linearRampToValueAtTime(r, now + (secs || 0.5));
  },

  /** 0..1 loudness of the music right now (cheap; call once per frame for pulsing lights/sky). */
  getLevel: function () {
    if (!analyser) return 0;
    analyser.getByteFrequencyData(levelData);
    var s = 0, n = 12; // low bins = kick/bass
    for (var i = 0; i < n; i++) s += levelData[i];
    return s / (n * 255);
  },

  /** Events: "ready", "trackchange" */
  on: function (ev, fn) { (listeners[ev] = listeners[ev] || []).push(fn); },

  /** Fallback for engines that want an <audio> element instead of Web Audio. */
  createAudioElement: function (name) {
    var a = new Audio(WEGA_MUSIC_DATA[name].src); a.loop = true; a.preload = "auto"; return a;
  }
};

global.WEGA_MUSIC_DATA = WEGA_MUSIC_DATA;
global.WegaMusic = WegaMusic;
if (typeof module !== "undefined" && module.exports) module.exports = WegaMusic;
})(typeof window !== "undefined" ? window : globalThis);
